package com.myassist.assistant.model;
import org.json.JSONObject;
public final class Models {public static class ServiceRequest {public int id,customerId;public Integer assistantId;public String assistantName,serviceType,description,pickupAddress,destinationAddress,status,createdAt;public double pickupLat,pickupLng,destLat,destLng;public static ServiceRequest fromJson(JSONObject o){ServiceRequest r=new ServiceRequest();r.id=o.optInt("id");r.customerId=o.optInt("customer_id");r.assistantId=o.isNull("assistant_id")?null:o.optInt("assistant_id");r.assistantName=o.optString("assistant_name",null);r.serviceType=o.optString("service_type");r.description=o.optString("description");r.pickupAddress=o.optString("pickup_address");r.pickupLat=o.optDouble("pickup_lat");r.pickupLng=o.optDouble("pickup_lng");r.destinationAddress=o.optString("destination_address");r.destLat=o.optDouble("destination_lat");r.destLng=o.optDouble("destination_lng");r.status=o.optString("status");r.createdAt=o.optString("created_at");return r;}}}